class Solution {
  public int minOperations(int n, int m) {
    int len = String.valueOf(n).length(), limit = 1;
    for (int i = 0; i < len; i++) limit *= 10;
    boolean[] composite = new boolean[limit];
    composite[0] = composite[1] = true;
    for (int i = 2; i < limit; i++) {
      if (composite[i]) continue;
      composite[i] = false;
      for (int j = i * i; j < limit; j += i) composite[j] = true;
    }
    // composite[] currently marks non-primes (0 and 1 included)
    boolean[] nonPrime = composite;
    if (!nonPrime[n] || !nonPrime[m]) return -1;
    long[] dist = new long[limit];
    java.util.Arrays.fill(dist, Long.MAX_VALUE);
    dist[n] = n;
    java.util.PriorityQueue<long[]> pq =
        new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
    pq.add(new long[] {n, n});
    while (!pq.isEmpty()) {
      long[] top = pq.poll();
      int u = (int) top[1];
      if (top[0] > dist[u]) continue;
      if (u == m) return (int) top[0];
      for (int p = 1; p < limit; p *= 10) {
        int digit = u / p % 10;
        if (digit < 9 && nonPrime[u + p] && top[0] + u + p < dist[u + p]) {
          dist[u + p] = top[0] + u + p;
          pq.add(new long[] {dist[u + p], u + p});
        }
        if (digit > 0 && nonPrime[u - p] && top[0] + u - p < dist[u - p]) {
          dist[u - p] = top[0] + u - p;
          pq.add(new long[] {dist[u - p], u - p});
        }
      }
    }
    return -1;
  }
}
